import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"运行当前测试与反馈循环","description":"","frontmatter":{},"headers":[],"relativePath":"testing/feedback-loop.md","filePath":"testing/feedback-loop.md"}'),n={name:"testing/feedback-loop.md"};function h(l,a,p,d,o,r){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="运行当前测试与反馈循环" tabindex="-1">运行当前测试与反馈循环 <a class="header-anchor" href="#运行当前测试与反馈循环" aria-label="Permalink to &quot;运行当前测试与反馈循环&quot;">​</a></h1><p>T01 的测试对象是第一条公开全栈请求。下面命令是真实检查，不是为尚未实现的 v1 功能放置的空门禁。</p><h2 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to &quot;后端&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-backend</span></span></code></pre></div><p>脚本创建独立 PostgreSQL 容器；SQLx 测试执行真实迁移。开发数据库的数据卷不会被测试清空。测试通过 Router 请求验证 liveness、readiness、公开错误/request_id、OpenAPI，以及真实数据库迁移状态。启动配置测试运行真实 API 可执行文件，检查失败是否发生在监听前且不会泄露凭据。</p><p>迁移测试还会持有真实 PostgreSQL 迁移锁，再运行迁移命令，验证它在配置的期限内失败退出；HTTP 测试用数据库锁验证查询不会无限等待。</p><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-frontend</span></span></code></pre></div><p>Vitest / Testing Library 操作真实 View，MSW 只替代 HTTP。测试覆盖从加载到成功、失败信息、request_id 和恢复后重试，以及服务无响应时结束加载并允许重试；每次测试创建新的 QueryClient。</p><h2 id="开发进程清理" tabindex="-1">开发进程清理 <a class="header-anchor" href="#开发进程清理" aria-label="Permalink to &quot;开发进程清理&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:tooling</span></span></code></pre></div><p>测试启动真实 HTTP 子进程，并让它忽略 SIGTERM。即使外层启动器先退出，停止开发服务也必须清理仍占用端口的子进程。测试观察服务是否还能响应，不依赖内部信号调用次数。</p><h2 id="真实浏览器" tabindex="-1">真实浏览器 <a class="header-anchor" href="#真实浏览器" aria-label="Permalink to &quot;真实浏览器&quot;">​</a></h2><p>首次准备 Chromium：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e</span></span></code></pre></div><p>E2E 创建独立数据库和动态端口，编译并运行真实 API，启动 Web 后通过 Chromium 访问。它检查响应来自实际接口，并暂停自己的数据库容器验证 readiness 失败而 liveness 存活，随后恢复。日志、失败截图和 trace 进入测试产物目录。</p><h2 id="主检查" tabindex="-1">主检查 <a class="header-anchor" href="#主检查" aria-label="Permalink to &quot;主检查&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>包括 Rust fmt/clippy、前端格式/lint/typecheck、合同漂移、边界检查、进程清理与后端/View 测试、文档检查及 Web/文档构建。日常检查不启动浏览器；关键旅程完成后运行 <code>just e2e</code>，里程碑完整验收运行 <code>just check-full</code>。CI 的手动入口可勾选 <code>run_e2e</code>，普通 push/PR 保留快速检查。尚未交付的 Mobile、长测与业务功能不伪装成已通过的检查。</p><h2 id="实施过程中的-red-→-green" tabindex="-1">实施过程中的 red → green <a class="header-anchor" href="#实施过程中的-red-→-green" aria-label="Permalink to &quot;实施过程中的 red → green&quot;">​</a></h2><p>本票依次先观察到：未注册路由返回 404、错误缺少 request_id、数据库未就绪却缺少 503 合同、未迁移数据库误报 ready、缺少 OpenAPI、错误配置继续监听，以及 View 不具备加载/失败反馈；然后逐条实现相应行为。</p><p>后续模块继续在已约定的公开入口上循环，不以内部方法调用次数或文件存在性代替行为。</p><hr><p>源码版本：<code>61c599464afc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/61c599464afc152695d7932084528b9cdb89c59b/docs/testing/t01-feedback-loop.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,24)])])}const b=e(n,[["render",h]]);export{k as __pageData,b as default};
